package ca.humber.stockbridge.security;
import ca.humber.stockbridge.repo.AppUserRepository;import org.springframework.context.annotation.*;import org.springframework.security.authentication.dao.DaoAuthenticationProvider;import org.springframework.security.core.userdetails.*;import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.security.web.SecurityFilterChain;import org.springframework.security.config.annotation.web.builders.HttpSecurity;
@Configuration public class SecurityConfig {@Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}@Bean UserDetailsService users(AppUserRepository repo){return email->repo.findByEmailIgnoreCase(email).orElseThrow(()->new UsernameNotFoundException("Account not found"));}@Bean SecurityFilterChain filter(HttpSecurity http)throws Exception{return http.authorizeHttpRequests(a->a.requestMatchers("/","/about","/how-it-works","/login","/register","/css/**","/error").permitAll().requestMatchers("/admin/**").hasRole("ADMIN").requestMatchers("/materials/new","/materials/*/edit","/materials/*/delete","/warehouses/**","/suppliers/**").hasAnyRole("ADMIN","MANAGER").anyRequest().authenticated()).formLogin(f->f.loginPage("/login").defaultSuccessUrl("/dashboard",true).permitAll()).logout(l->l.logoutSuccessUrl("/login?logout")).build();}}